   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你走上祭坛，拂去上面的积雪。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg_lymden/cg_16_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="下面露出了一块石板，石板上刻着稀奇古怪的符号，符号的痕迹已经有些淡了，有些部分很难辨认出来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg_lymden/cg_16_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可不知为何，看着这些符号，你却能直接明白其中的含义：", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg_lymden/cg_16_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="汝乃慈悲之暴君，冷酷之圣贤。\n星火将熄，然群星之御座不见汝之身影。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg_lymden/cg_16_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="寻那起始之源，\n纵亘古寰宇，万千闪耀之星为壤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg_lymden/cg_16_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
