   [135]={next_id=136, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="粗壮的光线再次交汇，牵动着十二颗巨星。漆黑星体无声地吞噬着周围的星光，拉扯着整片星海围绕着你缓缓旋转。", msg_color="", msg_size=0, talker="", audio="", img="", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
