   [139]={next_id=140, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="脉搏猛地跳动，你感到一股强大的力量从丝线中注入到你的身体，仿佛血管一样的东西伴随着钻心的头痛在脑中扩张。", msg_color="", msg_size=0, talker="", audio="", img="", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
