   [141]={next_id=142, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你咬紧牙关，双膝几乎跪倒在星海之上。", msg_color="", msg_size=0, talker="", audio="", img="", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [142]={next_id=143, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尊贵的存在啊……", msg_color="", msg_size=0, talker="低语", audio="", img="", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [143]={next_id=144, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="低沉的呼唤自群星间响起，此刻它再也不模糊，你很清晰地听到了那些絮语。", msg_color="", msg_size=0, talker="", audio="", img="", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [144]={next_id=145, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="往复寰宇百年，吾等渴求亦未泯灭。\n为何抛弃它们，为何将背叛族群？", msg_color="", msg_size=0, talker="", audio="", img="", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 1013.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
